<?php
require_once dirname(__DIR__,3).'/bootstrap.php';
$allowedRoles=[ROLE_ADMIN];require APP_ROOT.'/app/middleware/RoleMiddleware.php';
use App\Services\FirebaseService;use App\Services\HouseService;use App\Services\RoomService;use PhpOffice\PhpSpreadsheet\IOFactory;
if(isset($_GET['download_template'])){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="room_import_template.csv"');$out=fopen('php://output','w');fputcsv($out,['RoomNumber','HouseId','Capacity','Type','Status']);fputcsv($out,['A-101','HOUSE_ID',4,'standard','available']);fclose($out);exit;}
$errors=[];$success=0;if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='import_rooms'&&!empty($_FILES['rooms_file'])){$file=$_FILES['rooms_file'];$extension=strtolower(pathinfo($file['name']??'',PATHINFO_EXTENSION));if($file['error']!==UPLOAD_ERR_OK||!in_array($extension,['csv','xlsx'],true)){$errors[]='Upload a valid CSV or XLSX file.';}else{try{$rows=IOFactory::load($file['tmp_name'])->getActiveSheet()->toArray(null,true,true,false);$header=array_map(fn($value)=>strtolower(preg_replace('/[^a-z0-9]/i','',(string)$value)),array_shift($rows)?:[]);$map=[];foreach($header as $index=>$name)$map[$name]=$index;$defaultHouseId=sanitize($_POST['defaultHouseId']??'');foreach(array_slice($rows,0,1000) as $row){$value=fn($name,$fallback=-1)=>$row[$map[strtolower(preg_replace('/[^a-z0-9]/i','',$name))]??$fallback]??'';$roomNumber=sanitize($value('roomnumber',0));if($roomNumber===''){continue;}$houseId=sanitize($value('houseid',1)?:$defaultHouseId);RoomService::create(['roomNumber'=>$roomNumber,'houseId'=>$houseId,'capacity'=>max(1,(int)$value('capacity',2)),'type'=>sanitize($value('type',3)?:'standard'),'status'=>sanitize($value('status',4)?:'available')]);$success++;}flash('success',"Imported {$success} room(s) successfully.");redirect(url('views/admin/rooms/bulk-import.php'));}catch(Throwable $e){$errors[]='Import failed: '.$e->getMessage();}}}
$houses=HouseService::all();$pageTitle='Bulk Room Import';$navItems=[['icon'=>'bi-speedometer2','label'=>'Dashboard','href'=>url('views/admin/dashboard.php')],['icon'=>'bi-door-closed','label'=>'Rooms','href'=>url('views/admin/rooms/index.php')],['icon'=>'bi-upload','label'=>'Import Rooms','href'=>url('views/admin/rooms/bulk-import.php'),'active'=>true]];require APP_ROOT.'/app/views/components/header.php';require APP_ROOT.'/app/views/components/sidebar.php';?>
<div class="main-content"><?php require APP_ROOT.'/app/views/components/navbar.php';?><?php require APP_ROOT.'/app/views/components/alerts.php';?><div class="content-wrapper"><div class="card stat-card p-4" style="max-width:760px"><div class="d-flex justify-content-between mb-3"><h5>Import Rooms</h5><a class="btn btn-outline-secondary btn-sm" href="<?=url('views/admin/rooms/index.php')?>">Back</a></div><?php foreach($errors as $error):?><div class="alert alert-danger"><?=e($error)?></div><?php endforeach;?><form method="POST" enctype="multipart/form-data"><input type="hidden" name="action" value="import_rooms"><label class="form-label">CSV or XLSX file</label><input type="file" name="rooms_file" class="form-control mb-3" accept=".csv,.xlsx" required><label class="form-label">House</label><select name="defaultHouseId" class="form-select mb-3"><option value="">Use HouseId column</option><?php foreach($houses as $house):?><option value="<?=e((string)($house['id']??''))?>"><?=e($house['name']??'')?></option><?php endforeach;?></select><p class="small text-muted">Headers: RoomNumber, HouseId, Capacity, Type, Status. Maximum 1,000 rows.</p><button class="btn btn-primary">Upload and import</button> <a class="btn btn-outline-secondary" href="<?=url('views/admin/rooms/bulk-import.php?download_template=1')?>">Download template</a></form></div></div></div><?php require APP_ROOT.'/app/views/components/footer.php';?>